<script module lang="ts">
/**
 * An anchored, non-modal surface for rich content (`design/components/popover.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/popover.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { getContext, onDestroy, setContext, type Snippet } from 'svelte'

import * as zag from '@zag-js/popover'
import { useMachine } from '@zag-js/svelte'

import {
  Portal,
  agentMember,
  anchorProps,
  attributes,
  joinSlot,
  normalizeProps,
  syncTriggerAnchor,
  useDirection,
  useMediaQuery,
  watchEffect,
} from '@polymorph/svelte'
import { usePresence } from '@polymorph/svelte/motion'
import styles from '@polymorph/recipes/overlays/popover.module.css'
import sheet from '@polymorph/recipes/overlays/sheet.module.css'
import triggerAnchor from '@polymorph/recipes/overlays/trigger-anchor.module.css'

export type PopoverAlign = NonNullable<PopoverProps['align']>

export type PopoverSide = NonNullable<PopoverProps['side']>

export interface PopoverProps {
  align?: 'start' | 'center' | 'end'
  children: Snippet
  defaultOpen?: boolean
  /**
   * The panel's accessible name; required on purpose.
   */
  label: string
  onOpenChange?: (open: boolean) => void
  open?: boolean
  /**
   * `'auto'` stays anchored at every width, because Popover is non-modal by contract and a
   * default must not change that on phones only. `'sheet'` is the app's opt-in: unchanged above
   * `30rem`, and a modal bottom sheet below it (the sheet presentation,
   * `design/components/README.md`), as the spec states.
   */
  presentation?: 'auto' | 'sheet'
  side?: 'bottom' | 'top' | 'right' | 'left'
  trigger: Snippet
}
</script>

<script lang="ts">
let {
  align = 'start',
  children,
  defaultOpen,
  label: labelOwn,
  onOpenChange,
  open,
  presentation = 'auto',
  side = 'bottom',
  trigger,
}: PopoverProps = $props()
const uid = $props.id()
const joined = joinSlot(undefined, () => ({ label: labelOwn }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
const lender = getContext<{ element?: () => Element | null | undefined } | undefined>(
  'polymorph:borrowed',
)
setContext('polymorph:borrowed', undefined)
let anchor = $state<HTMLElement | null>(null)
let panel = $state<HTMLElement | null>(null)
let scrim = $state<HTMLElement | null>(null)
let sheetPanel = $state<HTMLElement | null>(null)
const phone = useMediaQuery('phone')
const sheeting = $derived(presentation === 'sheet' && phone.current)
const documentDirection = useDirection()
const service = useMachine(
  zag.machine,
  () =>
    ({
      id: uid,
      dir: documentDirection.current,
      open: open,
      defaultOpen: defaultOpen,
      modal: sheeting,
      positioning: {
        placement: align === 'center' ? side : `${side}-${align}`,
        offset: { mainAxis: 4 },
      },
      onOpenChange: (details) => {
        onOpenChange?.(details.open)
      },
    }) as Partial<zag.Props>,
)
const api = $derived(zag.connect(service, normalizeProps))
const present = usePresence(
  () => api.open && !sheeting,
  () => panel,
)
const sheetPresent = usePresence(
  () => api.open && sheeting,
  () => sheetPanel,
  'sheet.panel',
  { sheetSide: 'bottom' },
)
const scrimPresent = usePresence(
  () => api.open && sheeting,
  () => scrim,
  'dialog.scrim',
)
const effect1 = () => {
  syncTriggerAnchor(anchor, api.getTriggerProps(), api.open)
}
watchEffect(effect1, { watch: () => api.open })
const effect2 = () => {
  lender && (lender.element = () => panel ?? sheetPanel)
}
watchEffect(effect2)
let release3: (() => void) | undefined
const effect3 = () => {
  release3?.()
  const ran = lender
    ? () => {}
    : agentMember({
        member: 'Popover',
        element: () => panel ?? sheetPanel,
        state: () => ({ open: api.open }),
        actions: { close: () => api.open && api.setOpen(false) },
      })
  release3 = () => {
    ran()
  }
}
watchEffect(effect3)
onDestroy(() => release3?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<span
    bind:this={anchor}
    {...attributes(anchorProps(api.getTriggerProps()))}
    class={triggerAnchor.anchor}
    >{@render trigger?.()
  }</span
  ><Portal
    >{#if present.current
      }<div {...attributes(api.getPositionerProps())}
        ><div
          bind:this={panel}
          {...attributes(api.getContentProps())}
          class={styles.panel}
          style:--radix-popover-content-transform-origin={'var(--transform-origin)'}
          hidden={undefined}
          aria-labelledby={undefined}
          aria-describedby={undefined}
          aria-label={label}
          data-member="popover"
          >{@render children?.()
        }</div
      ></div
    >{/if
    }{#if scrimPresent.current
      }<div bind:this={scrim} class={sheet.scrim} data-state={api.open ? 'open' : 'closed'}></div
    >{/if
    }{#if sheetPresent.current
      }<div class={sheet.positioner}
        ><div
          bind:this={sheetPanel}
          {...attributes(api.getContentProps())}
          class={sheet.panel}
          hidden={undefined}
          aria-labelledby={undefined}
          aria-describedby={undefined}
          aria-label={label}
          data-presentation="sheet"
          ><div class={styles.sheetBody} data-member="popover">{@render children?.()}</div
        ></div
      ></div
    >{/if
  }</Portal
>{/if
}{@render joined.end?.()}
